<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/_helper.php';
uks_require_access($pdo);

$q=trim((string)($_GET['q']??''));
$status=(string)($_GET['status']??'');
$kelasId=max(0,(int)($_GET['kelas_id']??0));
$perPageInput=(int)($_GET['per_page']??20);
$perPage=in_array($perPageInput,[10,20,50,100],true)?$perPageInput:20;
$page=max(1,(int)($_GET['page']??1));
$teacherScope=uks_teacher_scope($pdo,'s');

$kelasSql="SELECT id,nama FROM master_kelas WHERE aktif=1";
if($teacherScope['sql']!=='1=1'){ $kelasSql.=" AND EXISTS(SELECT 1 FROM siswa_kelas skc INNER JOIN siswa sc ON sc.id=skc.siswa_id WHERE skc.kelas_id=master_kelas.id AND skc.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND skc.status='aktif' AND ".uks_teacher_scope($pdo,'sc')['sql'] . " )"; }
$kelasSql.=' ORDER BY tingkat,urutan,nama';
$kelasStmt=$pdo->prepare($kelasSql);
$kelasParams=[];
if($teacherScope['sql']!=='1=1'){$kelasParams=array_merge($kelasParams,uks_teacher_scope($pdo,'sc')['params']);}
$kelasStmt->execute($kelasParams);
$kelasRows=$kelasStmt->fetchAll();
$visitScopeSql="uk.siswa_id IN (SELECT s_scope.id FROM siswa s_scope WHERE ".uks_teacher_scope($pdo,'s_scope')['sql'] . ")";
$visitScopeParams=uks_teacher_scope($pdo,'s_scope')['params'];
$stats=[];
$stStats=$pdo->prepare("SELECT COUNT(*) FROM uks_kunjungan uk WHERE {$visitScopeSql}");$stStats->execute($visitScopeParams);$stats['kunjungan']=(int)$stStats->fetchColumn();
$stStats=$pdo->prepare("SELECT COUNT(*) FROM uks_kunjungan uk WHERE uk.tanggal=CURDATE() AND {$visitScopeSql}");$stStats->execute($visitScopeParams);$stats['hari_ini']=(int)$stStats->fetchColumn();
$stStats=$pdo->prepare("SELECT COUNT(*) FROM uks_kunjungan uk WHERE uk.status='selesai' AND {$visitScopeSql}");$stStats->execute($visitScopeParams);$stats['selesai']=(int)$stStats->fetchColumn();
$stats['obat_menipis']=(int)$pdo->query("SELECT COUNT(*) FROM uks_obat WHERE aktif=1 AND stok_saat_ini<=stok_minimum")->fetchColumn();
$stats['obat_kadaluarsa']=(int)$pdo->query("SELECT COUNT(*) FROM uks_obat WHERE aktif=1 AND tanggal_kadaluarsa IS NOT NULL AND tanggal_kadaluarsa<CURDATE()")->fetchColumn();
$stats['obat_30hari']=(int)$pdo->query("SELECT COUNT(*) FROM uks_obat WHERE aktif=1 AND tanggal_kadaluarsa IS NOT NULL AND tanggal_kadaluarsa>=CURDATE() AND tanggal_kadaluarsa<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
$refScopeSql="r.siswa_id IN (SELECT s_ref.id FROM siswa s_ref WHERE ".uks_teacher_scope($pdo,'s_ref')['sql'].")";
$refScopeParams=uks_teacher_scope($pdo,'s_ref')['params'];
$stRef=$pdo->prepare("SELECT COUNT(*) FROM uks_rujukan r WHERE r.tanggal=CURDATE() AND {$refScopeSql}");$stRef->execute($refScopeParams);$stats['rujukan_hari_ini']=(int)$stRef->fetchColumn();
$stRef=$pdo->prepare("SELECT COUNT(*) FROM uks_rujukan r WHERE r.status IN ('direncanakan','dirujuk') AND {$refScopeSql}");$stRef->execute($refScopeParams);$stats['rujukan_pending']=(int)$stRef->fetchColumn();
$refSt=$pdo->prepare("SELECT r.id,r.tanggal,r.status,r.tujuan_jenis,r.fasilitas_nama,s.nama,s.nis FROM uks_rujukan r JOIN siswa s ON s.id=r.siswa_id WHERE r.status IN ('direncanakan','dirujuk') AND {$refScopeSql} ORDER BY r.tanggal DESC,r.id DESC LIMIT 5");$refSt->execute($refScopeParams);$rujukanPending=$refSt->fetchAll();
$where=['1=1'];$params=[];
if($teacherScope['sql']!=='1=1'){ $where[]=$teacherScope['sql']; $params=array_merge($params,$teacherScope['params']); }
if($q!==''){ $where[]='(s.nis LIKE ? OR s.nisn LIKE ? OR s.nama LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like); }
if($status!=='' && in_array($status,['baru','ditangani','selesai','batal'],true)){ $where[]='uk.status=?';$params[]=$status; }
if($kelasId>0){$where[]="EXISTS(SELECT 1 FROM siswa_kelas skf WHERE skf.siswa_id=s.id AND skf.kelas_id=? AND skf.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND skf.status='aktif')";$params[]=$kelasId;}
$count=$pdo->prepare("SELECT COUNT(*) FROM uks_kunjungan uk JOIN siswa s ON s.id=uk.siswa_id WHERE ".implode(' AND ',$where));$count->execute($params);$total=(int)$count->fetchColumn();
$pages=max(1,(int)ceil($total/max(1,$perPage)));if($page>$pages)$page=$pages;$offset=($page-1)*$perPage;
$sql="SELECT uk.id,uk.tanggal,uk.waktu,uk.status,uk.keluhan,s.nis,s.nisn,s.nama,mk.nama AS kelas,g.nama AS petugas
 FROM uks_kunjungan uk JOIN siswa s ON s.id=uk.siswa_id
 LEFT JOIN guru g ON g.id=uk.petugas_id
 LEFT JOIN master_kelas mk ON mk.id=uk.kelas_id
 WHERE ".implode(' AND ',$where)." ORDER BY uk.tanggal DESC,uk.waktu DESC,uk.id DESC LIMIT $perPage OFFSET $offset";
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
function rujukan_label_jenis(string $v): string { return ['puskesmas'=>'Puskesmas','rumah_sakit'=>'Rumah Sakit','klinik'=>'Klinik','lainnya'=>'Lainnya'][$v]??$v; }
function rujukan_label_status(string $v): string { return ['direncanakan'=>'Direncanakan','dirujuk'=>'Dirujuk','selesai'=>'Selesai','tidak_jadi'=>'Tidak jadi'][$v]??$v; }
function uks_query(array $changes=[]):string{$base=$_GET??[];unset($base['page']);foreach($changes as $k=>$v){if($v===null)unset($base[$k]);else$base[$k]=$v;}return http_build_query($base);}
$flash=uks_flash();
$page_title='UKS';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
