<?php if($rujukanPending):?><div class="uks-panel uks-table"><div class="uks-head"><div><h2><i class="bi bi-hospital-fill"></i> Rujukan Perlu Tindak Lanjut</h2><p>Rujukan dengan status Direncanakan atau Dirujuk.</p></div><a href="<?=BASE_URL?>uks/rujukan.php">Lihat semua <i class="bi bi-arrow-right"></i></a></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Siswa</th><th>Tujuan</th><th>Fasilitas</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rujukanPending as $rr):?><tr><td><strong><?=e($rr['nama'])?></strong><div class="meta"><?=e($rr['nis'])?></div></td><td><?=e(rujukan_label_jenis($rr['tujuan_jenis']))?></td><td><?=e($rr['fasilitas_nama'])?></td><td><?=e($rr['tanggal'])?></td><td><span class="badge <?=e($rr['status'])?>"><?=e(rujukan_label_status($rr['status']))?></span></td><td><a class="btn btn-sm btn-secondary" title="Detail" href="<?=BASE_URL?>uks/rujukan.php?id=<?=$rr['id']?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach;?></tbody></table></div></div><?php endif; ?>
<div class="uks-panel uks-table"><div class="uks-head"><div><h2><i class="bi bi-clock-history"></i> Kunjungan Terbaru</h2><p><?=number_format($total)?> data sesuai filter.</p></div></div><form method="get" class="uks-filter"><label><span class="form-label">Cari</span><input class="form-control" type="search" name="q" value="<?=e($q)?>" placeholder="NIS / NISN / Nama"></label><label><span class="form-label">Kelas</span><select class="form-control" name="kelas_id"><option value="0">Semua Kelas</option><?php foreach($kelasRows as $k):?><option value="<?=$k['id']?>" <?=$kelasId===(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select></label><label><span class="form-label">Status</span><select class="form-control" name="status"><option value="">Semua</option><option value="baru" <?=$status==='baru'?'selected':''?>>Baru</option><option value="ditangani" <?=$status==='ditangani'?'selected':''?>>Ditangani</option><option value="selesai" <?=$status==='selesai'?'selected':''?>>Selesai</option><option value="batal" <?=$status==='batal'?'selected':''?>>Batal</option></select></label><label><span class="form-label">Per Halaman</span><select class="form-control" name="per_page"><?php foreach([10,20,50,100] as $n):?><option value="<?=$n?>" <?=$perPage===$n?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><button class="btn btn-primary" type="submit"><i class="bi bi-funnel-fill"></i> Terapkan</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/index.php"><i class="bi bi-arrow-counterclockwise"></i> Reset</a></form><div class="table-responsive" style="margin-top:14px"><table class="data-table"><thead><tr><th>Siswa</th><th>Kelas</th><th>Tanggal</th><th>Status</th><th>Petugas</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty-state">Belum ada kunjungan.</td></tr><?php else:foreach($rows as $r):?><tr><td><div class="student"><div class="avatar"><i class="bi bi-person-fill"></i></div><div><strong><?=e($r['nama'])?></strong><div class="meta"><?=e($r['nis'])?><?=!empty($r['nisn'])?' · '.e($r['nisn']):''?></div></div></div></td><td><?=e($r['kelas']??'-')?></td><td><?=e($r['tanggal'])?><?=!empty($r['waktu'])?' '.e($r['waktu']):''?></td><td><span class="badge <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?=e($r['petugas']??'-')?></td><td style="white-space:nowrap"><a class="btn btn-sm btn-secondary" title="Detail" href="<?=BASE_URL?>uks/kunjungan_detail.php?id=<?=$r['id']?>"><i class="bi bi-eye"></i></a><?php if(uks_can_manage($pdo)):?><a class="btn btn-sm btn-primary" title="Edit" href="<?=BASE_URL?>uks/kunjungan_edit.php?id=<?=$r['id']?>"><i class="bi bi-pencil-square"></i></a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($pages>1):?><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-top:15px"><div style="font-size:12px;color:#64748b">Halaman <?=$page?> dari <?=$pages?></div><div class="pages"><?php if($page>1):?><a href="?<?=e(uks_query(['page'=>$page-1]))?>"><i class="bi bi-chevron-left"></i></a><?php endif;?><?php $start=max(1,$page-2);$end=min($pages,$page+2);for($p=$start;$p<=$end;$p++):?><a class="<?=$p===$page?'active':''?>" href="?<?=e(uks_query(['page'=>$p]))?>"><?=$p?></a><?php endfor;?><?php if($page<$pages):?><a href="?<?=e(uks_query(['page'=>$page+1]))?>"><i class="bi bi-chevron-right"></i></a><?php endif;?></div></div><?php endif;?></div>
